/**
 * Backup retention may ONLY delete files generated by the corresponding
 * Beacon job. Never delete an administrator's arbitrary .dump files.
 */
const STAMP = '\\d{8}-\\d{6}';
const REGULAR = new RegExp('^(?:beacon|diddybot9000)-backup-' + STAMP + '\\.dump$');
const DRILL = new RegExp('^restore-drill-' + STAMP + '\\.dump$');

export function isManagedBackupFilename(name, kind = 'regular') {
  if (typeof name !== 'string') return false;
  return kind === 'drill' ? DRILL.test(name) : REGULAR.test(name);
}
